def maxDistance(words):
    n = len(words)
    best = 0

    # Pair with the left end: farthest j with words[j] != words[0]; distance j - 0 + 1
    for j in range(n - 1, -1, -1):
        if words[j] != words[0]:
            best = max(best, j + 1)
            break

    # Pair with the right end: farthest-left i with words[i] != words[-1]; distance (n-1) - i + 1
    for i in range(n):
        if words[i] != words[-1]:
            best = max(best, n - i)
            break

    return best
